#include <iostream>
#include <variant>
#include <string>
struct Add { int amount{}; };
struct Remove { int amount{}; };
using Command = std::variant<Add, Remove>;
bool executeStock(int& stock, const Command& command) {
    if (const auto* add = std::get_if<Add>(&command)) {
        if (add->amount < 0 || add->amount > 1000 - stock) { return false; }
        stock += add->amount;
        return true;
    }
    const auto* remove = std::get_if<Remove>(&command);
    if (!remove || remove->amount < 0 || remove->amount > stock) { return false; }
    stock -= remove->amount;
    return true;
}
int main() {
    int stock{}, amount{};
    std::string kind;
    if (!(std::cin >> stock >> kind >> amount)) { std::cout << "invalid\n"; return 0; }
    std::cin >> std::ws;
    if (!std::cin.eof() || stock < 0 || stock > 1000 || amount < 0 || amount > 1000 || (kind != "add" && kind != "remove")) { std::cout << "invalid\n"; return 0; }
    Command value = Add{amount};
    if (kind == "remove") { value = Remove{amount}; }
    bool ok = executeStock(stock, value);
    std::cout << (ok ? "ok " : "rejected ") << stock << '\n';
}
